package com.enterprise.siem;
import com.enterprise.siem.detection.*; import com.enterprise.siem.model.*; import org.junit.jupiter.api.Test; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class RuleTest { private SecurityEvent event(String node,EventType type,int second){return new SecurityEvent(null,Instant.parse("2026-01-01T00:00:00Z").plusSeconds(second),node,node,"WARN","sshd","event","10.0.0.50",null,"admin",type,Map.of());}
 @Test void bruteForceUsesWindow(){var c=new RuleContext();var r=new BruteForceRule(5,60);for(int i=0;i<4;i++)assertFalse(r.evaluate(event("n1",EventType.AUTH_FAILURE,i),c));assertTrue(r.evaluate(event("n1",EventType.AUTH_FAILURE,4),c));assertFalse(r.evaluate(event("n1",EventType.AUTH_FAILURE,100),c));}
 @Test void distributedNeedsMultipleAgents(){var c=new RuleContext();var r=new DistributedBruteForceRule(2,300);assertFalse(r.evaluate(event("n1",EventType.AUTH_FAILURE,1),c));assertFalse(r.evaluate(event("n1",EventType.AUTH_FAILURE,2),c));assertFalse(r.evaluate(event("n2",EventType.AUTH_FAILURE,3),c));assertTrue(r.evaluate(event("n2",EventType.AUTH_FAILURE,4),c));}
 @Test void suspiciousLoginNeedsSuccessAfterFailures(){var c=new RuleContext();var r=new SuspiciousLoginRule(300);for(int i=0;i<3;i++)assertFalse(r.evaluate(event("n1",EventType.AUTH_FAILURE,i),c));assertTrue(r.evaluate(event("n1",EventType.AUTH_SUCCESS,4),c));}
 @Test void suspiciousLoginDoesNotTriggerOnFailureAfterSuccess(){var c=new RuleContext();var r=new SuspiciousLoginRule(300);for(int i=0;i<3;i++)assertFalse(r.evaluate(event("n1",EventType.AUTH_FAILURE,i),c));assertTrue(r.evaluate(event("n1",EventType.AUTH_SUCCESS,4),c));assertFalse(r.evaluate(event("n1",EventType.AUTH_FAILURE,5),c));}
 @Test void distributedGlobalThresholdUsesTotalFailures(){var c=new RuleContext();var r=new DistributedBruteForceRule(4,300,Severity.CRITICAL,true);assertFalse(r.evaluate(event("n1",EventType.AUTH_FAILURE,1),c));assertFalse(r.evaluate(event("n2",EventType.AUTH_FAILURE,2),c));assertFalse(r.evaluate(event("n1",EventType.AUTH_FAILURE,3),c));assertTrue(r.evaluate(event("n2",EventType.AUTH_FAILURE,4),c));}
}
